import{_ as n,W as l,s as o,u as d,I as s,ah as g,w as t,Z as e,A as p}from"./chunks/framework.DYeiaKBS.js";import"./chunks/theme.DJBbXXYU.js";const y=JSON.parse('{"title":"你应该知道的基础 Git 命令 | LCTT x X-CMD","titleTemplate":false,"description":"你应该知道的基础 Git 命令 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你应该知道的基础 Git 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你应该知道的基础 Git 命令 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160606 Basic Git Commands You Must Know","title":"你应该知道的基础 Git 命令","tag":"201607"},"relativePath":"201607/20160606 Basic Git Commands You Must Know.md","filePath":"[post].md"}'),h={name:"201607/20160606 Basic Git Commands You Must Know.md"};function r(c,a,u,b,m,v){const i=l("Link");return d(),o("div",null,[a[21]||(a[21]=s("h1",{id:"你应该知道的基础-git-命令",tabindex:"-1"},[t("你应该知道的基础 Git 命令 "),s("a",{class:"header-anchor",href:"#你应该知道的基础-git-命令","aria-label":"Permalink to 你应该知道的基础 Git 命令"},"​")],-1)),a[22]||(a[22]=s("p",null,[s("img",{src:"http://itsfoss.com/wp-content/uploads/2016/06/Download-Git-Sheet.jpg",alt:""})],-1)),a[23]||(a[23]=s("p",null,[s("em",null,"简介：这个快速指南将向你展示所有的基础 Git 命令以及用法。你可以下载这些命令作为快速参考。")],-1)),s("p",null,[a[1]||(a[1]=t("我们在早先一篇文章中已经快速介绍过 ")),e(i,{href:"http://itsfoss.com/download-vi-cheat-sheet/"},{default:p(()=>a[0]||(a[0]=[t("Vi 速查表")])),_:1}),a[2]||(a[2]=t("了。在这篇文章里，我们将会介绍开始使用 Git 时所需要的基础命令。"))]),a[24]||(a[24]=s("h3",{id:"git",tabindex:"-1"},[t("Git "),s("a",{class:"header-anchor",href:"#git","aria-label":"Permalink to Git"},"​")],-1)),s("p",null,[e(i,{href:"https://git-scm.com/"},{default:p(()=>a[3]||(a[3]=[t("Git")])),_:1}),a[5]||(a[5]=t(" 是一个分布式版本控制系统，它被用在大量开源项目中。它是在 2005 年由 Linux 创始人 ")),e(i,{href:"https://en.wikipedia.org/wiki/Linus_Torvalds"},{default:p(()=>a[4]||(a[4]=[t("Linus Torvalds")])),_:1}),a[6]||(a[6]=t(" 写就的。这个程序允许非线性的项目开发，并且能够通过存储在本地服务器高效处理大量数据。在这个教程里，我们将要和 Git 愉快玩耍并学习如何开始使用它。"))]),a[25]||(a[25]=g(`<p>我在这个教程里使用 Ubuntu，但你可以使用你选择的任何发行版。除了安装以外，剩下的所有命令在任何 Linux 发行版上都是一样的。</p><h3 id="安装-git" tabindex="-1">安装 Git <a class="header-anchor" href="#安装-git" aria-label="Permalink to 安装 Git">​</a></h3><p>要安装 git 执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install git-core</span></span></code></pre></div><p>在它完成下载之后，你就安装好了 Git 并且可以使用了。</p><h3 id="设置-git" tabindex="-1">设置 Git <a class="header-anchor" href="#设置-git" aria-label="Permalink to 设置 Git">​</a></h3><p>在 Git 安装之后，不论是从 apt-get 还是从源码安装，你需要将你的用户名和邮箱地址复制到 gitconfig 文件。你可以访问 ~/.gitconfig 这个文件。</p><p>全新安装 Git 之后打开它会是完全空白的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim ~/.gitconfig</span></span></code></pre></div><p>你也可以使用以下命令添加所需的信息。将‘user’替换成你的用户名，‘user@example.com’替换成你的邮箱。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global user.name &quot;User&quot;</span></span>
<span class="line"><span>git config --global user.email user@example.com</span></span></code></pre></div><p>然后你就完成设置了。现在让我们开始 Git。</p><h3 id="仓库" tabindex="-1">仓库 <a class="header-anchor" href="#仓库" aria-label="Permalink to 仓库">​</a></h3><p>创建一个新目录，打开它并运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git init</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/Playing-around-git-1-1024x173.png" alt=""></p><p>这个命令会创建一个新的 Git 仓库（repository）。你的本地仓库由三个 Git 维护的“树”组成。</p><p>第一个是你的工作目录（Working Directory），保存实际的文件。第二个是索引，实际上扮演的是暂存区（staging area），最后一个是 HEAD，它指向你最后一个 commit 提交。使用 git clone /path/to/repository 签出你的仓库（从你刚创建的仓库或服务器上已存在的仓库）。</p><h3 id="添加文件并提交" tabindex="-1">添加文件并提交 <a class="header-anchor" href="#添加文件并提交" aria-label="Permalink to 添加文件并提交">​</a></h3><p>你可以用以下命令添加改动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git add &lt;filename&gt;</span></span></code></pre></div><p>这会添加一个新文件到暂存区以提交。如果你想添加每个新文件，输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git add --all</span></span></code></pre></div><p>添加文件之后可以使用以下命令检查状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git status</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/Playing-around-git-2-1024x219.png" alt=""></p><p>正如你看到的，那里已经有一些变化但还没有提交。现在你需要提交这些变化，使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git commit -m &quot;提交信息&quot;</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/playing-around-git-3-1024x124.png" alt=""></p><p>你也可以这么做（首选）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git commit -a</span></span></code></pre></div><p>然后写下你的提交信息。现在你的文件提交到了 HEAD，但还不在你的远程仓库中。</p><h3 id="推送你的改动" tabindex="-1">推送你的改动 <a class="header-anchor" href="#推送你的改动" aria-label="Permalink to 推送你的改动">​</a></h3><p>你的改动在你本地工作副本的 HEAD 中。如果你还没有从一个已存在的仓库克隆，或想将你的仓库连接到远程服务器，你需要先添加它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote add origin &lt;服务器地址&gt;</span></span></code></pre></div><p>现在你可以将改动推送到指定的远程服务器。要将改动发送到远程服务器，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push -u origin master</span></span></code></pre></div><h3 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to 分支">​</a></h3><p>分支用于开发特性，分支之间是互相独立的。主分支 master 是你创建一个仓库时的“默认”分支。使用其它分支用于开发，在完成时将它合并回主分支。</p><p>创建一个名为“mybranch”的分支并切换到它之上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout -b mybranch</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/Playing-around-Git-4--1024x145.jpg" alt=""></p><p>你可以使用这个命令切换回主分支：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git checkout master</span></span></code></pre></div><p>如果你想删除这个分支，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git branch -d mybranch</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/Playing-around-Git-5-1-1024x181.jpg" alt=""></p><p>除非你将分支推送到远程服务器上，否则该分支对其他人是不可用的，所以只需把它推送上去：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push origin &lt;分支名&gt;</span></span></code></pre></div><h3 id="更新和合并" tabindex="-1">更新和合并 <a class="header-anchor" href="#更新和合并" aria-label="Permalink to 更新和合并">​</a></h3><p>要将你本地仓库更新到最新的提交上，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git pull</span></span></code></pre></div><p>在你的工作目录获取并合并远程变动。要合并其它分支到你的活动分支（如 master），使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git merge &lt;分支&gt;</span></span></code></pre></div><p>在这两种情况下，git 会尝试自动合并（auto-merge）改动。不幸的是，这不总是可能的，可能会导致冲突。你需要通过编辑 git 所显示的文件，手动合并那些冲突。改动之后，你需要用以下命令将它们标记为已合并：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git add &lt;文件名&gt;</span></span></code></pre></div><p>在合并改动之前，你也可以使用以下命令预览：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git diff &lt;源分支&gt; &lt;目标分支&gt;</span></span></code></pre></div><h3 id="git-日志" tabindex="-1">Git 日志 <a class="header-anchor" href="#git-日志" aria-label="Permalink to Git 日志">​</a></h3><p>你可以这么查看仓库历史：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git log</span></span></code></pre></div><p>要以每个提交一行的样式查看日志，你可以用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git log --pretty=oneline</span></span></code></pre></div><p>或者也许你想要看一个所有分支的 ASCII 艺术树，带有标签和分支名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git log --graph --oneline --decorate --all</span></span></code></pre></div><p>如果你只想看哪些文件改动过：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git log --name-status</span></span></code></pre></div><p>在这整个过程中如果你需要任何帮助，你可以用 git --help。</p><p>Git 棒不棒？！祝贺你你已经会 Git 基础了。如果你愿意的话，你可以从下面这个链接下载这些基础 Git 命令作为快速参考：</p>`,69)),s("ul",null,[s("li",null,[e(i,{href:"https://drive.google.com/open?id=0By49_3Av9sT1bXpINjhvU29VNUU"},{default:p(()=>a[7]||(a[7]=[t("下载 Git 速查表")])),_:1})])]),a[26]||(a[26]=s("hr",null,null,-1)),s("p",null,[a[9]||(a[9]=t("via: ")),e(i,{href:"http://itsfoss.com/basic-git-commands-cheat-sheet/"},{default:p(()=>a[8]||(a[8]=[t("http://itsfoss.com/basic-git-commands-cheat-sheet/")])),_:1})]),s("p",null,[a[13]||(a[13]=t("作者：")),e(i,{href:"http://itsfoss.com/author/rakhi/"},{default:p(()=>a[10]||(a[10]=[t("Rakhi Sharma")])),_:1}),a[14]||(a[14]=t(" 译者：")),e(i,{href:"https://github.com/alim0x"},{default:p(()=>a[11]||(a[11]=[t("alim0x")])),_:1}),a[15]||(a[15]=t(" 校对：")),e(i,{href:"https://github.com/wxy"},{default:p(()=>a[12]||(a[12]=[t("wxy")])),_:1})]),s("p",null,[a[18]||(a[18]=t("本文由 ")),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>a[16]||(a[16]=[t("LCTT")])),_:1}),a[19]||(a[19]=t(" 原创编译，")),e(i,{href:"https://linux.cn/"},{default:p(()=>a[17]||(a[17]=[t("Linux中国")])),_:1}),a[20]||(a[20]=t(" 荣誉推出"))])])}const f=n(h,[["render",r]]);export{y as __pageData,f as default};
